// Search box and category filters for the plugin catalog (docs/catalog.md, generated by
// scripts/generate_catalog.py). The controls start hidden, so without JavaScript the page is a
// plain list of every plugin.
//
// Instant navigation swaps pages without a reload, so this runs on each page change through
// `document$` when it exists, and once the DOM is ready otherwise.

(function () {
  function setUp() {
    const filters = document.querySelector(".plugin-filters");
    const catalog = document.querySelector(".plugin-catalog");
    if (!filters || !catalog || filters.dataset.ready) return;
    filters.dataset.ready = "true";

    let extra = {};
    try {
      extra = JSON.parse(catalog.dataset.extra || "{}");
    } catch (e) {
      extra = {};
    }
    const search = filters.querySelector(".plugin-search");
    const buttons = Array.from(filters.querySelectorAll("[data-category]"));
    const count = filters.querySelector(".plugin-count");
    const list = catalog.querySelector(":scope > ul");
    if (!list) return;
    const cards = Array.from(list.children).map((card) => {
      // The card's id comes from its link to the plugin's page (catalog/<id>/).
      const page = card.querySelector('a[href*="catalog/"]');
      const id = page ? (/catalog\/([a-z0-9-]+)/.exec(page.getAttribute("href")) || [])[1] : "";
      return {
        element: card,
        text: (card.textContent + " " + (extra[id] || "") + " " + (id || "")).toLowerCase(),
        categories: new Set(Array.from(card.querySelectorAll("code"), (tag) => tag.textContent)),
      };
    });
    const selected = new Set();

    function apply() {
      const words = search.value.toLowerCase().split(/\s+/).filter(Boolean);
      let shown = 0;
      for (const card of cards) {
        const visible =
          words.every((word) => card.text.includes(word)) &&
          (selected.size === 0 || [...selected].some((c) => card.categories.has(c)));
        card.element.style.display = visible ? "" : "none";
        card.element.hidden = !visible;
        if (visible) shown += 1;
      }
      const noun = cards.length === 1 ? "plugin" : "plugins";
      count.textContent = shown === cards.length ? `${cards.length} ${noun}` : `${shown} of ${cards.length} ${noun}`;
    }

    for (const event of ["input", "search", "keyup"]) search.addEventListener(event, apply);
    for (const button of buttons) {
      button.addEventListener("click", () => {
        const c = button.dataset.category;
        if (selected.has(c)) selected.delete(c);
        else selected.add(c);
        button.setAttribute("aria-pressed", String(selected.has(c)));
        apply();
      });
    }
    filters.hidden = false;
    apply();
  }

  if (typeof document$ !== "undefined" && document$.subscribe) {
    document$.subscribe(setUp);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", setUp);
  else setUp();
})();
